import { motion } from 'framer-motion';
import React from 'react';
import { Metric } from '../../models';
import { cn } from '../../utilities/cn';


interface MetricCardProps {
  metric: Metric;
  active: boolean;
  onClick: () => void;
}

const MetricCard: React.FC<MetricCardProps> = ({ metric, active, onClick }) => (
  <motion.div
    whileHover={{ y: -2 }}
    onClick={onClick}
    className={cn(
      'flex flex-col p-4 bg-white rounded-xl border transition-all cursor-pointer min-w-[160px] flex-1',
      active
        ? 'border-blue-500 ring-1 ring-blue-500 shadow-lg shadow-blue-100'
        : 'border-slate-100 hover:border-blue-200 shadow-sm'
    )}
  >
    <div className="flex justify-between items-start mb-3">
      <div className={cn('p-2 rounded-lg', metric.bgColor)}>
        <metric.icon size={18} className={metric.color} />
      </div>
      <span
        className={cn(
          'text-[10px] font-bold px-2 py-0.5 rounded-full',
          metric.status === 'CRITICAL'
            ? 'bg-red-100 text-red-600'
            : metric.status === 'ACTIVE'
            ? 'bg-blue-100 text-blue-600'
            : 'bg-slate-100 text-slate-500'
        )}
      >
        {metric.status}
      </span>
    </div>
    <div className="mt-auto">
      <div className="text-2xl font-bold text-slate-800">{metric.value.toString().padStart(2, '0')}</div>
      <div className="text-[11px] text-slate-500 font-medium leading-tight mt-1">{metric.label}</div>
    </div>
  </motion.div>
);

export default MetricCard;
